{#- Sidra Sale Quotation print (SAL-05; decision G13). Cash and installment options side by side. -#}
<style>
	.sidra-sq { font-size: 11pt; }
	.sidra-sq h2 { margin-bottom: 4px; }
	.sidra-sq h3 { margin: 18px 0 6px; border-bottom: 1px solid #999; }
	.sidra-sq table { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
	.sidra-sq th, .sidra-sq td { border: 1px solid #bbb; padding: 3px 6px; vertical-align: top; text-align: left; }
	.sidra-sq td.num, .sidra-sq th.num { text-align: right; }
	.sidra-sq .draft { color: #a00; font-weight: bold; }
	.sidra-sq .note { color: #555; font-size: 9.5pt; }
</style>
<div class="sidra-sq">
	<div class="sidra-letterhead" style="text-align:center;margin-bottom:8px"><img src="{{ frappe.utils.get_url() }}/assets/sidra_realestate/images/sidra-logo.png" alt="Sidra Homes" style="height:60px"></div>
	<h2>Sale Quotation {{ doc.name | e }}</h2>
	{% if doc.docstatus == 0 %}<p class="draft">Draft — not yet issued</p>{% endif %}
	{% if doc.docstatus == 2 %}<p class="draft">Cancelled</p>{% endif %}

	<table>
		<tr><th>From</th><td>{{ doc.company | e }}</td><th>Customer</th><td>{{ frappe.db.get_value("Customer", doc.customer, "customer_name") | e }}</td></tr>
		<tr><th>Date</th><td>{{ doc.get_formatted("quotation_date") }}</td><th>Valid until</th><td>{{ doc.get_formatted("valid_until") }}</td></tr>
	</table>

	<h3>Units</h3>
	<table>
		<tr><th>Unit</th><th>Location</th><th>Size</th><th class="num">Cash price</th><th class="num">Installment price</th></tr>
		{% for row in doc.units %}
		{%- set u = frappe.db.get_value("Sidra Unit", row.unit, ["dimensions", "plot_fraction", "district", "neighbourhood"], as_dict=True) or {} -%}
		<tr>
			<td>{{ row.unit | e }}<br>{{ (row.scheme or "") | e }}</td>
			<td>{{ (u.district or "") | e }}{% if u.neighbourhood %}, {{ u.neighbourhood | e }}{% endif %}</td>
			<td>{{ (u.dimensions or "") | e }}{% if u.plot_fraction %} ({{ u.plot_fraction | e }}){% endif %}</td>
			<td class="num">{{ row.get_formatted("cash_price", doc) }}</td>
			<td class="num">{{ row.get_formatted("installment_price", doc) }}</td>
		</tr>
		{% endfor %}
	</table>

	<h3>Your two options</h3>
	<table>
		<tr><th></th><th class="num">Cash</th><th class="num">Installments</th></tr>
		<tr><th>Total price</th><td class="num"><strong>{{ doc.get_formatted("cash_total") }}</strong></td><td class="num"><strong>{{ doc.get_formatted("installment_total") }}</strong></td></tr>
		<tr><th>Paid at signing</th><td class="num">{{ doc.get_formatted("cash_total") }}</td><td class="num">{{ doc.get_formatted("down_payment") }}</td></tr>
		<tr><th>Paid in installments</th><td class="num">—</td><td class="num">{{ doc.get_formatted("balance") }} in {{ doc.installments }} monthly installments</td></tr>
		<tr><th>Payment day</th><td class="num">—</td><td class="num">Day {{ doc.due_day }} of each month</td></tr>
	</table>

	<h3>Indicative installment schedule</h3>
	<table>
		<tr><th>No.</th><th>Due date</th><th class="num">Amount</th></tr>
		{% for row in doc.schedule %}
		<tr><td>{{ row.seq }}</td><td>{{ row.get_formatted("due_date") }}</td><td class="num">{{ row.get_formatted("amount", doc) }}</td></tr>
		{% endfor %}
	</table>
	<p class="note">The schedule assumes the contract is signed on {{ doc.get_formatted("quotation_date") }}; the signed contract's own schedule applies. This quotation is an offer valid until {{ doc.get_formatted("valid_until") }}. It does not reserve the unit and is not a contract or a receipt.</p>
	{% if doc.notes %}<p>{{ doc.notes | e }}</p>{% endif %}
</div>
